DROP TEMPORARY TABLE IF EXISTS `look_items`;
CREATE TEMPORARY TABLE `look_items` AS SELECT m.`new_entry`, m.`new_name`, m.`new_display`, t.* FROM `look_map` m JOIN `item_template` t ON t.`entry` = m.`src_entry` AND t.`patch` = 0;
UPDATE `look_items` SET `entry` = `new_entry`, `name` = `new_name`, `display_id` = `new_display`;
